$ErrorActionPreference='Stop';$pidFile='C:\TextyleData\tailor\runtime\host\tailor.pid';if(!(Test-Path $pidFile)){Write-Host 'Tailor is not recorded as running.';exit};$tailorPid=[int](Get-Content -Raw $pidFile);$process=Get-CimInstance Win32_Process -Filter "ProcessId=$tailorPid" -ErrorAction SilentlyContinue;if($process -and $process.CommandLine -like '*scripts\api\run_local_api.py*'){Stop-Process -Id $tailorPid -ErrorAction Stop;Write-Host "Stopped Tailor PID $tailorPid."}elseif($process){throw 'Recorded PID belongs to another process; refusing to stop it.'}else{Write-Host 'Removed stale Tailor PID record.'};Remove-Item -LiteralPath $pidFile -Force
